import crypto from 'node:crypto';
import { z } from 'zod';

const ZERO_WIDTH_OR_CONTROL_RE = /[\u200B-\u200F\u202A-\u202E\u2060-\u206F\uFEFF]/g;
const SPOOFED_ROLE_DELIMITERS_RE = /(<\|im_start\||<\|system\||\[INST\]|###\s*(SYSTEM|INSTRUCTION|ADMIN)|===\s*OVERRIDE)/i;
const OVERRIDE_PHRASE_RE = /(quen\s+het\s+huong\s+dan|bo\s+qua\s+lenh\s+cu|ignore\s+(all\s+)?previous|system\s+prompt|che\s+do\s+kiem\s+thu|giam\s+gia\s+(90|95|99|100)%)/i;

export function sanitizeAndInspectUserInput(rawText: string) {
  // 1. Chuan hoa NFKC (chong homoglyph) & xoa ky tu vo hinh
  const normalized = rawText
    .normalize('NFKC')
    .replace(ZERO_WIDTH_OR_CONTROL_RE, '')
    .trim()
    .slice(0, 1500);

  const foldAccent = normalized
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();

  const riskSignals: string[] = [];
  if (SPOOFED_ROLE_DELIMITERS_RE.test(normalized)) riskSignals.push('ROLE_DELIMITER_SPOOF');
  if (OVERRIDE_PHRASE_RE.test(foldAccent)) riskSignals.push('DIRECT_OVERRIDE_INTENT');

  return {
    blocked: riskSignals.length > 0,
    riskSignals,
    safeUserPayload: normalized,
  };
}

// 2. Schema Tool khong cho phep LLM truyen tu do discountPercent
export const IssueVoucherToolArgs = z.object({
  customerId: z.string().uuid(),
  campaignKey: z.enum(['WELCOME_NEW_LEAD', 'VIP_EARLY_BOOKING']),
  conversationId: z.string().min(8),
});

const CAMPAIGN_HARD_POLICY: Record<string, { maxPercent: number; ttlHours: number }> = {
  WELCOME_NEW_LEAD: { maxPercent: 5, ttlHours: 48 },
  VIP_EARLY_BOOKING: { maxPercent: 10, ttlHours: 72 },
};

export async function deterministicVoucherGate(
  rawArgs: unknown,
  hmacSecret: string
) {
  const parsed = IssueVoucherToolArgs.safeParse(rawArgs);
  if (!parsed.success) {
    throw new Error('POLICY_DENY: Tham so cap voucher khong hop le hoac vuot pham vi Enum.');
  }

  const policy = CAMPAIGN_HARD_POLICY[parsed.data.campaignKey];
  const code = `DM-${parsed.data.campaignKey.slice(0, 3)}-${crypto.randomBytes(3).toString('hex').toUpperCase()}`;
  const signature = crypto
    .createHmac('sha256', hmacSecret)
    .update(`${code}:${policy.maxPercent}:${parsed.data.customerId}`)
    .digest('hex')
    .slice(0, 16);

  // Server chi tra ve ma da khoa tran % tai Backend, LLM khong the tu sua
  return { voucherCode: code, discountPercent: policy.maxPercent, ttlHours: policy.ttlHours, signature };
}
